      "html_path": "works/gregory-nazianzus-oration-29/index.html#p-18",
      "label": "제3신학강론 (제29강론) 18",
      "location": "18",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:6d87b47b4106494cf07b17cc7e28506062b6c7eed0bc07413c0340e8fe889c6e",
        "text": "Σὺ δέ μοι καταρίθμει πρὸς ταῦτα τὰ τῆς ἀγνωμοσύνης ῥήματα, τὸ θεός μου καὶ θεὸς ὑμῶν, τὸ μείζων, τὸ ἔκτισε, τὸ ἐποίησε, τὸ ἡγίασεν. εἰ βούλει δέ, καὶ τὸ δοῦλον, καὶ τὸ ὑπήκοον· τὸ δέδωκε, τὸ ἔμαθε, τὸ ἐντέταλται, τὸ ἀπέσταλται, τὸ μὴ δύνασθαι ἀφ’ ἑαυτοῦ τι ποιεῖν, ἢ λέγειν, ἢ κρίνειν, ἢ δωρεῖσθαι, ἢ βούλεσθαι. ἔτι δὲ καὶ ταῦτα, τὴν ἄγνοιαν, τὴν ὑποταγήν, τὴν εὐχήν, τὴν ἐρώτησιν, τὴν προκοπήν, τὴν τελείωσιν. πρόσθες, εἰ βούλει, καὶ ὅσα τούτων ταπεινότερα, τὸ ὑπνοῦν, τὸ πεινῆν, τὸ κοπιᾷν, τὸ δακρύειν, τὸ ἀγωνιᾷν, τὸ ὑποδύεσθαι. τάχα δ’ ἂν ὀνειδίσαις καὶ τὸν σταυρόν, καὶ τὸν θάνατον. τὴν γὰρ ἔγερσιν καὶ τὴν ἀνάληψιν παρήσειν μοι δοκεῖς, ἐπειδή τι καὶ πρὸς ἡμῶν ἐν τούτοις εὑρίσκεται. πολλὰ δ’ ἂν ἔτι πρὸς τούτοις σπερμολογήσαις, εἰ βούλοιο συντιθέναι τὸν ὁμώνυμόν σου θεὸν καὶ παρέγγραπτον, ἡμῖν δὲ ἀληθινὸν καὶ ὁμότιμον. τούτων γὰρ ἕκαστον οὐ χαλεπὸν μὲν καὶ κατὰ μέρος ἐπεξιόντα ἐξηγεῖσθαί σοι πρὸς τὸ εὐσεβέστατον, καὶ ἀνακαθαίρειν τὸ ἐν τοῖς γράμμασι πρόσκομμα, εἴ γε προσπταίεις ὄντως, ἀλλὰ μὴ ἑκὼν κακουργεῖς. ἑνὶ δὲ κεφαλαίῳ, τὰ μὲν ὑψηλότερα πρόσαγε τῇ θεότητι καὶ τῇ κρείττονι φύσει παθῶν καὶ σώματος· τὰ δὲ ταπεινότερα τῷ συνθέτῳ, καὶ τῷ διὰ σὲ κενωθέντι καὶ σαρκωθέντι, οὐδὲν δὲ χεῖρον εἰπεῖν, καὶ ἀνθρωπισθέντι, εἶτα καὶ ὑψωθέντι, ἵνα σὺ τὸ τῶν δογμάτων σου σαρκικὸν καὶ χαμαιπετὲς καταλύσας μάθης ὑψηλότερος εἶναι, καὶ συνανιέναι θεότητι, καὶ μὴ τοῖς ὁρωμένοις ἐναπομένοις, ἀλλὰ συνεπαίρῃ τοῖς νοουμένοις, καὶ γινώσκῃς, τίς μὲν φύσεως λόγος, τίς δὲ λόγος οἰκονομίας."
      },
      "title": "제3신학강론 (제29강론)",
      "translation": {
        "notes": [
          "낮은 표현에는 요한복음 20:17과 14:28, 잠언 8:22, 사도행전 2:36, 요한복음 10:36, 빌립보서 2:7-8 등의 말이 들어 있다. 뒤의 제4신학강론(제30강론)에서 이 표현들을 더 자세히 설명한다.",
          "οἰκονομία는 구원을 위해 인간이 되신 일을 가리키므로 ‘구원의 경륜’으로 옮겼다. 본성에 관한 높은 표현과 인간이 되신 분에 관한 낮은 표현을 함께 읽는 해석 원칙이다."
        ],
        "revision_id": "sha256:e5eb65803aaefab91f687367a25ad2795a6b3bbdea30dcdbc29bc295557e101e",
        "text": "이에 맞서 그대는 분별없는 해석에 쓰는 표현들을 내게 늘어놓으라. ‘내 하나님과 너희 하나님’, ‘더 크시다’, ‘창조하셨다’, ‘만드셨다’, ‘거룩하게 하셨다’라는 표현들이다. 원한다면 ‘종’과 ‘순종하는 분’도 더하라. ‘주셨다’, ‘배우셨다’, ‘명령을 받으셨다’, ‘보내심을 받으셨다’, ‘스스로 무엇을 행하거나 말하거나 판단하거나 베풀거나 원하실 수 없다’라는 표현들도 더하라. 알지 못하심, 복종하심, 기도하심, 물으심, 자라나심, 온전하게 되심도 더하라. 원한다면 이보다 더 낮은 것들도 덧붙이라. 주무심, 주리심, 지치심, 우심, 괴로워하심, 물러서심이다. 아마 그대는 십자가와 죽음까지 비난할 것이다. 부활과 승천은 빼놓을 것 같다. 거기에는 우리 편에 유리한 무엇도 있기 때문이다. 그대가 이름만 같고 위조된 하나님을 꾸며 내고 싶다면, 이 밖에도 많은 말을 주워 모을 수 있을 것이다. 그러나 우리에게 아들은 참 하나님이시며 동등한 존엄을 지니신 분이다. 이 각각을 따로 살펴, 가장 경건한 뜻으로 그대에게 설명하는 일은 어렵지 않다. 글자에 걸려 넘어지는 일을 없애는 것도 어렵지 않다. 그대가 일부러 해를 끼치려는 것이 아니라 실제로 걸려 넘어진다면 말이다. 한마디로 말하자면, 높은 표현들은 신성과, 정념과 몸보다 높은 본성에 적용하라. 낮은 표현들은 결합된 분, 그대를 위해 자신을 비우고 육신이 되신 분에게 적용하라. 인간이 되셨다고 말해도 무방하다. 그 뒤에 높임을 받으셨다. 그대가 가르침의 육체적이고 땅으로 기우는 생각을 무너뜨리고 더 높아지는 법을 배우게 하려는 것이다. 신성과 함께 올라가며, 보이는 것들에 머무르지 않고, 생각으로 깨닫는 것들과 함께 높아져 알게 하려는 것이다. 무엇이 본성에 관한 말이고, 무엇이 구원의 경륜에 관한 말인지 알게 하려는 것이다."
      },
