      "html_path": "works/gregory-nazianzus-oration-30/index.html#p-2",
      "label": "제4신학강론 (제30강론) 2",
      "location": "2",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:dcd5df95eaf2547c8cb97c672af43206aab93ae1ef1340a3346d4cca1d8a52e3",
        "text": "Ἔστι γὰρ ἓν μὲν αὐτοῖς ἐκεῖνο καὶ λίαν πρόχειρον τό· Κύριος ἔκτισέ με ἀρχὴν ὁδῶν αὐτοῦ εἰς ἔργα αὐτοῦ. πρὸς ὃ πῶς ἀπαντησόμεθα; οὐ Σολομῶντος κατηγορήσομεν; οὐ τὰ πρὶν ἀθετήσομεν διὰ τὴν τελευταίαν παράπτωσιν; οὐχὶ τῆς σοφίας αὐτῆς ἐροῦμεν εἶναι τὸν λόγον, τῆς οἷον ἐπιστήμης καὶ τοῦ τεχνίτου λόγου, καθ’ ὃν τὰ πάντα συνέστη; πολλὰ γὰρ ἡ γραφὴ προσωποποιεῖν οἶδε καὶ τῶν ἀψύχων, ὡς τό· Ἡ θάλασσα εἶπε τάδε καὶ τάδε· καί, Ἡ ἄβυσσος εἶπεν, οὐκ ἔστιν ἐν ἐμοί· καί, Οἱ οὐρανοὶ διηγούμενοι δόξαν θεοῦ· καὶ πάλιν ῥομφαία τι διακελεύεται, καὶ ὄρη καὶ βουνοὶ λόγους ἐρωτῶνται σκιρτήσεως. τούτων οὐδέν φαμεν, εἰ καί τισι τῶν πρὸ ἡμῶν ὡς ἰσχυρὰ τέθειται. ἀλλ’ ἔστω τοῦ σωτῆρος αὐτοῦ, τῆς ἀληθινῆς σοφίας, ὁ λόγος. μικρὸν δὲ συνδιασκεψώμεθα. τί τῶν ὄντων ἀναίτιον; θεότης. οὐδεὶς γὰρ αἰτίαν εἰπεῖν ἔχει θεοῦ· ἢ τοῦτο ἂν εἴη θεοῦ πρεσβύτερον. τίς δὲ τῆς ἀνθρωπότητος, ἣν δι’ ἡμᾶς ὑπέστη θεός, αἰτία; τὸ σωθῆναι πάντως ἡμᾶς. τί γὰρ ἕτερον; ἐπειδὴ τοίνυν ἐνταῦθα καὶ τὸ ἔκτισε καὶ τὸ Γεννᾷ με σαφῶς εὑρίσκομεν, ἁπλοῦς ὁ λόγος. ὃ μὲν ἂν μετὰ τῆς αἰτίας εὑρίσκωμεν, προσθῶμεν τῇ ἀνθρωπότητι· ὃ δὲ ἁπλοῦν καὶ ἀναίτιον, τῇ θεότητι λογισώμεθα. ἆρ’ οὖν οὐ τὸ μὲν ἔκτισεν εἴρηται μετὰ τῆς αἰτίας; Ἔκτισε γάρ μέ, φησιν, ἀρχὴν ὁδῶν αὐτοῦ εἰς ἔργα αὐτοῦ. ἔργα δὲ χειρῶν αὐτοῦ ἀλήθεια καὶ κρίσις, ὧν ἕνεκεν ἐχρίσθη θεότητι. χρίσις γὰρ αὕτη τῆς ἀνθρωπότητος. τὸ δὲ Γεννᾷ με χωρὶς αἰτίας· ἢ δεῖξόν τι τούτῳ προσκείμενον. τίς οὖν ἀντερεῖ λόγος, κτίσμα μὲν λέγεσθαι τὴν σοφίαν κατὰ τὴν κάτω γέννησιν, γέννημα δὲ κατὰ τὴν πρώτην καὶ πλέον ἄληπτον;"
      },
      "title": "제4신학강론 (제30강론)",
      "translation": {
        "notes": [
          "잠언 8:22의 ‘창조하셨다’와 8:25의 ‘낳으신다’를 함께 읽는다. 그레고리오스는 구원의 목적이 붙은 창조 표현을 인간성에, 이유가 덧붙지 않은 탄생 표현을 신성에 연결한다.",
          "바다와 심연의 말은 욥기 28:14, 하늘의 선포는 시편 19:1, 칼에 대한 명령은 스가랴 13:7, 산과 언덕에 대한 질문은 시편 114:6과 연결된다. 의인화라는 해석도 소개한 뒤 구주 자신이 말하는 경우를 논한다.",
          "‘그분 손의 일들은 진리와 심판’은 시편 111:7의 표현이다. 이 장의 αἰτία는 신성이 있게 된 원인을 묻는 경우와 인간이 되신 구원의 이유를 묻는 경우에 쓰인다."
        ],
        "revision_id": "sha256:053a948e828af0af30873c1cf05c37d6f8c70de486e3cb3cd1decf91c2860cfd",
        "text": "그들에게 특히 손쉽게 쓸 수 있는 첫째 표현은 이것이다. “주님께서 자신의 일들을 위해, 자신의 길들의 시작으로 나를 창조하셨다.” 이에 어떻게 대답하겠는가? 솔로몬을 비난하겠는가? 마지막의 잘못 때문에 이전의 말들을 배척하겠는가? 이 말이 지혜 자체, 곧 모든 것을 이루는 지식과 장인의 원리에 관한 것이라고 하겠는가? 성경은 생명 없는 것들도 많이 의인화하기 때문이다. 예를 들어, “바다가 이러이러한 말을 했다”라는 말이 있다. 또 “심연이 ‘내 안에는 없다’라고 말했다.” 또 “하늘들이 하나님의 영광을 이야기한다.” 다시, 칼에게 무엇을 명하기도 하고, 산과 언덕에게 왜 뛰노는지 묻기도 한다. 우리는 그 어느 것도 말하지 않겠다. 우리보다 앞선 어떤 이들은 그것들을 강한 논거로 세웠지만 말이다. 이것은 구주 자신, 참 지혜께서 하시는 말이라고 하자. 조금 함께 살펴보자. 존재하는 것들 가운데 무엇이 이유 없이 있는가? 신성이다. 누구도 하나님의 원인을 말할 수 없기 때문이다. 그런 원인이 있다면 하나님보다 앞설 것이다. 그런데 하나님께서 우리를 위해 취하신 인간성의 이유는 무엇인가? 분명히 우리의 구원이다. 그 밖에 무엇이겠는가? 그러므로 여기에서 ‘창조하셨다’와 ‘나를 낳으신다’를 모두 분명히 발견하니, 설명은 간단하다. 이유와 함께 나오는 말은 인간성에 적용하자. 아무 조건도 이유도 없이 나오는 말은 신성에 적용하자. ‘창조하셨다’라는 말은 이유와 함께 하지 않았는가? “그분은 자신의 일들을 위해, 자신의 길들의 시작으로 나를 창조하셨다”라고 말하기 때문이다. 그분 손의 일들은 진리와 심판이며, 이것들을 위해 신성으로 기름부음을 받으셨다. 이것이 인간성의 기름부음이다. ‘나를 낳으신다’에는 이유가 없다. 또는 거기에 붙은 어떤 이유를 제시해 보라. 그러므로 지혜를 아래의 탄생에 따라 피조물이라고 부르고, 첫 번째이며 더 붙잡기 어려운 탄생에 따라 태어나신 분이라고 부르는 데, 무슨 논증으로 반대하겠는가?"
      },
