      "html_path": "works/gregory-nazianzus-oration-30/index.html#p-10",
      "label": "제4신학강론 (제30강론) 10",
      "location": "10",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:591849605e66b2d47576cbeaeb8f75186fff4c51ac69a4bdffa9ec8b7b617ac3",
        "text": "Ἕκτον τιθέσθω τὸ μὴ δύνασθαι τὸν υἱὸν ἀφ’ ἑαυτοῦ ποιεῖν μηδέν, ἐὰν μή τι βλέπῃ τὸν πατέρα ποιοῦντα. τοῦτο δὲ τοιοῦτόν ἐστιν· οὐ τῶν καθ’ ἕνα τρόπον λεγομένων τὸ δύνασθαι ἢ μὴ δύνασθαι· πολύσημον δέ. τὸ μὲν γάρ τι λέγεται κατὰ δυνάμεως ἔλλειψιν, καί ποτε, καὶ πρός τι, ὡς τὸ μὴ δύνασθαι τὸ παιδίον ἀθλεῖν, ἢ τὸ σκυλάκιον βλέπειν, ἢ πρὸς τόνδε διαγωνίζεσθαι. ἀθλήσει γὰρ ἴσως ποτέ, καὶ ὄψεται, καὶ διαγωνιεῖται πρὸς τόνδε, κἂν πρὸς ἕτερον ἀδυνάτως ἔχῃ. τὸ δέ, ὡς ἐπὶ πλεῖστον, ὡς τό· Οὐ δύναται πόλις κρυβῆναι ἐπ’ ἄνω ὄρους κειμένη. τάχα γὰρ ἂν καὶ κρυφθείη τις, ἐπιπροσθοῦντος μείζονος. τὸ δέ, ὡς οὐκ εὔλογον· Οὐ δύνανται οἱ υἱοὶ τοῦ νυμφῶνος νηστεύειν, ἐφ’ ὅσον ἔνδημος ὁ νυμφίος· εἴτε ὁ σωματικῶς ὁρώμενος· οὐ γὰρ κακοπαθείας, ἀλλ’ εὐφροσύνης καιρὸς ὁ τῆς ἐπιδημίας· εἴτε ὁ ὡς λόγος νοούμενος. τί γὰρ δεῖ νηστεύειν σωματικῶς τοὺς λόγῳ καθαιρομένους; τὸ δέ, ὡς ἀβούλητον, ὡς τὸ μὴ δύνασθαι ἐκεῖ σημεῖα ποιῆσαι, διὰ τὴν ἀπιστίαν τῶν δεχομένων. ἐπειδὴ γὰρ τοῦ συναμφοτέρου χρεία πρὸς τὰς ἰάσεις, καὶ τῆς τῶν θεραπευομένων πίστεως, καὶ τῆς τοῦ θεραπευτοῦ δυνάμεως, οὐκ ἐνεδέχετο τὸ ἕτερον τοῦ συζύγου ἐλλείποντος. οὐκ οἶδα δέ, εἰ μὴ καὶ τοῦτο τῷ εὐλόγῳ προσθετέον· οὐ γὰρ εὔλογος ἴασις τοῖς βλαβησομένοις ἐξ ἀπιστίας. τοῦ δὲ αὐτοῦ λόγου καὶ τό· Οὐ δύναται ὁ κόσμος μὴ μισεῖν ὑμᾶς· καί, Πῶς δύνασθε ἀγαθὰ λαλεῖν, πονηροὶ ὄντες; πῶς γὰρ ἀδύνατόν τι τούτων, ἢ ὅτι ἀβούλητον; ἔστι δέ τι καὶ τοιοῦτον ἐν τοῖς λεγομένοις, ὃ τῇ φύσει μὲν ἀδύνατον, θεῷ δὲ δυνατὸν βουληθέντι, ὡς τὸ μὴ δύνασθαι τὸν αὐτὸν γεννηθῆναι δεύτερον· καὶ ῥαφὶς οὐκ εἰσδεχομένη κάμηλον. τί γὰρ ἂν καὶ κωλύσειε γενέσθαι ταῦτα θεοῦ θελήσαντος;"
      },
      "title": "제4신학강론 (제30강론)",
      "translation": {
        "notes": [
          "요한복음 5:19의 ‘할 수 없다’를 해설하기 전에, 능력 부족, 대체로 그러함, 합당하지 않음, 원하지 않음, 자연적으로 불가능함이라는 여러 용례를 나눈다.",
          "산 위의 도시는 마태복음 5:14, 혼인 잔치의 금식은 마가복음 2:19, 고향에서의 표적은 마가복음 6:5 및 마태복음 13:58, 두 번째 탄생은 요한복음 3:4의 표현이다.",
          "세상이 미워한다는 인용에는 μὴ가 들어 있어 ‘미워하지 않을 수 없다’로 옮겼다. 요한복음 7:7의 문장과는 형태가 다르며, Mason은 요한복음 15:18 이하의 표현이 겹쳐 있다고 설명한다(122쪽)."
        ],
        "revision_id": "sha256:3ea511946d7b27d5fe202e942c7c87e42bf6c864e16dc4ff92ac52fa7d4e7da8",
        "text": "여섯째로, 아들은 아버지께서 하시는 일을 보지 않으면 스스로 아무것도 할 수 없다는 말을 들자. 이 말은 이렇다. 할 수 있음과 할 수 없음은 한 가지 뜻으로만 쓰이지 않으며, 여러 뜻을 가진다. 어떤 것은 능력의 부족 때문에, 어떤 때나 어떤 상대에 대하여 할 수 없다고 한다. 아이가 운동 경기에 나설 수 없다는 말이 그러하다. 강아지가 볼 수 없다는 말이나, 어떤 상대와 겨룰 수 없다는 말도 그러하다. 언젠가는 경기에 나서고 보게 되며, 다른 상대와는 겨루지 못하더라도 그 상대와는 겨룰 수 있을 것이다. 어떤 것은 대개 그러하다는 뜻이다. “산 위에 있는 도시는 숨길 수 없다”라는 말이 그러하다. 더 큰 무엇이 앞을 가리면, 어떤 도시는 숨길 수도 있을 것이다. 어떤 것은 합당하지 않다는 뜻이다. “신랑이 함께 있는 동안, 혼인 잔치의 손님들은 금식할 수 없다.” 눈에 보이는 육신의 신랑이라면, 함께 있는 때는 괴로움의 때가 아니라 즐거움의 때이기 때문이다. 말씀으로 이해하는 신랑이라면, 말씀으로 정결해지는 이들이 몸으로 금식할 필요가 무엇인가? 어떤 것은 원하지 않는다는 뜻이다. 그분이 받는 이들의 불신 때문에 그곳에서 표적을 행하실 수 없었다는 말이 그러하다. 치유에는 두 가지가 함께 필요하기 때문이다. 치유받는 이들의 믿음과 치유하는 분의 능력이 필요하다. 함께 있어야 할 하나가 부족하면, 다른 하나도 이루어질 수 없었다. 이것도 합당함에 관한 설명에 넣어야 하는지 나는 모르겠다. 불신 때문에 해를 입을 사람들을 치유하는 일은 합당하지 않기 때문이다. 다음 말도 같은 설명에 속한다. “세상은 너희를 미워하지 않을 수 없다.” 또 “너희가 악한데, 어떻게 선한 말을 할 수 있는가?” 원하지 않기 때문이 아니라면, 이것들 가운데 무엇이 불가능하겠는가? 다음과 같은 종류의 표현도 있다. 본성으로는 불가능하지만 하나님께서 원하시면 가능한 것이다. 같은 사람이 두 번째로 태어날 수 없다는 말이 그러하다. 바늘이 낙타를 받아들이지 못한다는 말도 그러하다. 하나님께서 원하시면 이것들이 이루어지는 데 무엇이 장애가 되겠는가?"
      },
