      "html_path": "works/gregory-nazianzus-oration-30/index.html#p-15",
      "label": "제4신학강론 (제30강론) 15",
      "location": "15",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:79bb3cba031e49d4a38f0698b357030da61f657e53e31343cf02c8c53eeb2906",
        "text": "Δέκατον αὐτοῖς ἐστιν ἡ ἄγνοια, καὶ τὸ μηδένα γινώσκειν τὴν τελευταίαν ἡμέραν ἢ ὥραν, μηδὲ τὸν υἱὸν αὐτόν, εἰ μὴ τὸν πατέρα. καίτοι πῶς ἀγνοεῖ τι τῶν ὄντων ἡ σοφία, ὁ ποιητὴς τῶν αἰώνων, ὁ συντελεστὴς καὶ μεταποιητής, τὸ πέρας τῶν γενομένων; ὁ οὕτω τὰ τοῦ θεοῦ γινώσκων, ὡς τὸ πνεῦμα τοῦ ἀνθρώπου τὰ ἐν αὐτῷ; τί γὰρ ταύτης τῆς γνώσεως τελεώτερον; πῶς δὲ τὰ μὲν πρὸ τῆς ὥρας ἀκριβῶς ἐπίσταται, καὶ τὰ οἷον ἐν χρῷ τοῦ τέλους, αὐτὴν δὲ ἀγνοεῖ τὴν ὥραν; αἰνίγματι γὰρ τὸ πρᾶγμα ὅμοιον, ὥσπερ ἂν εἴ τις τὰ μὲν πρὸ τοῦ τείχους ἀκριβῶς ἐπίστασθαι λέγοι, αὐτὸ δὲ ἀγνοεῖν τὸ τεῖχος· ἢ τὸ τῆς ἡμέρας τέλος εὖ ἐπιστάμενος, τὴν ἀρχὴν τῆς νυκτὸς μὴ γινώσκειν· ἔνθα ἡ τοῦ ἑτέρου γνῶσις ἀναγκαίως συνεισάγει τὸ ἕτερον. ἢ πᾶσιν εὔδηλον, ὅτι γινώσκει μέν, ὡς θεός, ἀγνοεῖν δέ φησιν, ὡς ἄνθρωπος, ἄν τις τὸ φαινόμενον χωρίσῃ τοῦ νοουμένου; τὸ γὰρ ἀπόλυτον εἶναι τὴν τοῦ υἱοῦ προσηγορίαν καὶ ἄσχετον, οὐ προσκειμένου τῷ υἱῷ τοῦ τίνος, ταύτην ἡμῖν δίδωσι τὴν ὑπόνοιαν, ὥστε τὴν ἄγνοιαν ὑπολαμβάνειν ἐπὶ τὸ εὐσεβέστερον, τῷ ἀνθρωπίνῳ, μὴ τῷ θείῳ, ταύτην λογιζομένους."
      },
      "title": "제4신학강론 (제30강론)",
      "translation": {
        "notes": [
          "마지막 날과 시간을 알지 못하심은 마가복음 13:32의 표현이다. 지혜이시며 시대들의 창조자이신 분에 관한 표현들과 함께 비교한다.",
          "성벽과 낮밤의 경계는 바로 앞의 일을 정확히 알면서 그 끝을 모른다고 하는 설명을 시험하는 비유이다. 신성과 인간성을 구별하여 알지 못하심을 인간적인 면에 연결한다."
        ],
        "revision_id": "sha256:3d6719c87fb9bbfc96708f14d28babcf048c37c78a060125d4c13d74b63e9114",
        "text": "그들의 열째 논거는 알지 못하심이다. 마지막 날이나 시간을 아무도 모르고, 아들 자신도 모르며, 아버지만 아신다는 말이다. 그러나 지혜이시며 시대들을 만드시고 완성하고 변화시키시는 분, 생겨난 것들의 끝이신 분이 존재하는 것들 가운데 무엇을 어떻게 모르시는가? 그분은 인간의 영이 자기 안의 것을 알듯 하나님의 일을 아시는 분이다. 이 지식보다 더 온전한 것이 무엇인가? 그 시간 이전의 일들과 끝에 바짝 가까운 일들은 정확히 아시면서, 그 시간 자체는 어떻게 모르시는가? 이것은 수수께끼 같다. 어떤 사람이 성벽 앞의 것들은 정확히 알지만, 성벽 자체는 모른다고 말하는 것과 같다. 또는 낮의 끝은 잘 알면서 밤의 시작은 모른다고 말하는 것과 같다. 여기에서는 한쪽을 알면 반드시 다른 쪽도 함께 알게 된다. 하나님으로서는 아시고, 인간으로서는 모른다고 말씀하신다는 것이 누구에게나 분명하지 않은가? 보이는 것과 생각으로 깨닫는 것을 구별한다면 말이다. 아들이라는 호칭에 누구의 아들인지 덧붙지 않고, 독립적으로 관계의 한정 없이 쓰인다. 이 때문에 우리는 알지 못하심을 더 경건하게 이해하여, 신적인 면이 아닌 인간적인 면에 적용할 수 있다."
      },
      "work_id": "gregory-nazianzus-oration-30",
      "work_passage_id": "gregory-nazianzus-oration-30:15"
