      "html_path": "works/gregory-nazianzus-oration-31/index.html#p-22",
      "label": "제5신학강론 (제31강론) 22",
      "location": "22",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:17a8db0e27ed96d1fec972f039f15e6d38fc6c1b5c2266bb81694097f5542f4c",
        "text": "τῶν πραγμάτων τὰ μὲν οὐκ ἔστι, λέγεται δέ· τὰ δὲ ὄντα οὐ λέγεται· τὰ δὲ οὔτε ἔστιν, οὔτε λέγεται· τὰ δὲ ἄμφω, καὶ ἔστι, καὶ λέγεται. τούτων ἀπαιτεῖς με τὰς ἀποδείξεις; παρασχεῖν ἕτοιμος. ὑπνοῖ τῇ γραφῇ θεός, καὶ γρηγορεῖ, καὶ ὀργίζεται, καὶ βαδίζει, καὶ θρόνον ἔχει τὰ χερουβίμ· καίτοι πότε γέγονεν ἐμπαθής; πότε δὲ σῶμα θεὸν ἀκήκοας; τοῦτο οὐκ ὂν ἀνεπλάσθη. ὠνομάσαμεν γάρ, ὡς ἡμῖν ἐφικτόν, ἐκ τῶν ἡμετέρων τὰ τοῦ θεοῦ. τὸ μὲν ἠρεμεῖν αὐτὸν ἀφ’ ἡμῶν, καὶ οἷον ἀμελεῖν, δι’ ἃς αὐτὸς οἶδεν αἰτίας, ὑπνοῦν. τὸ γὰρ ἡμέτερον ὑπνοῦν τοιοῦτον, ἀνενέργητόν τε καὶ ἄπρακτον. τὸ δὲ ἀθρόως εὖ ποιεῖν ἐκ μεταβολῆς, γρηγορεῖν. ὕπνου γὰρ λύσις ἐγρήγορσις, ὥσπερ ἀποστροφῆς ἐπίσκεψις. τὸ δὲ κολάζειν ὀργίζεσθαι πεποιήκαμεν· οὕτω γὰρ ἡμῖν ἐξ ὀργῆς ἡ κόλασις. τὸ δὲ νῦν μὲν τῇδε, νῦν δὲ τῇδε ἐνεργεῖν, βαδίζειν. ἡ γὰρ ἀπ’ ἄλλου πρὸς ἄλλο μετάβασις, βαδισμός. τὸ δὲ ἐναναπαύεσθαι ταῖς ἁγίαις δυνάμεσι, καὶ οἷον ἐμφιλοχωρεῖν, καθέζεσθαι καὶ θρονίζεσθαι. καὶ τοῦτο ἡμέτερον. οὐδενὶ γὰρ οὕτως ὡς τοῖς ἁγίοις τὸ θεῖον ἐναναπαύεται. τὸ δὲ ὀξυκίνητον, πτῆσιν· τὴν δὲ ἐπισκοπήν, πρόσωπον· τὸ διδόναι δὲ καὶ προσίεσθαι, χεῖρα· καὶ ἄλλη τις ὅλως τῶν τοῦ θεοῦ δυνάμεων ἢ ἐνεργειῶν ἄλλο τι τῶν σωματικῶν ἡμῖν ἀνεζωγράφησεν."
      },
      "title": "제5신학강론 (제31강론)",
      "translation": {
        "notes": [
          "실재와 말의 관계를 네 경우로 나눈 뒤, 실제로 그렇지 않으면서 그렇게 말하는 성경의 표현들을 먼저 설명한다. 잠과 깨어남, 분노와 걸음, 보좌와 얼굴과 손이 그 예이다.",
          "잠은 시편 44:23, 걸음은 창세기 3:8, 케루빔의 보좌는 시편 80:1과 에스겔 1:26, 날아가심은 시편 18:10의 표현을 활용한다. 인간의 경험으로 하나님의 활동을 이름 붙이는 방식을 설명한다."
        ],
        "revision_id": "sha256:e93790557d0ce7dd9cee7e2ba854fa6e83cbf40dace7060648d1f5d82f170f11",
        "text": "어떤 것들은 실제로 그렇지 않지만 그렇게 말해진다. 어떤 것들은 실제로 있지만 말해지지 않는다. 어떤 것들은 실제로 있지도 않고 말해지지도 않는다. 어떤 것들은 둘 다이며, 실제로 있고 말해지기도 한다. 그대는 이것들의 증거를 요구하는가? 나는 제시할 준비가 되어 있다. 성경에서 하나님은 주무시고 깨어나시며, 화내시고 걸으시며, 케루빔을 보좌로 삼으신다. 그러나 언제 정념에 사로잡힌 분이 되셨는가? 언제 하나님이 몸을 지니셨다고 들었는가? 실제로 그렇지 않은 것을 형상으로 표현했다. 우리가 이를 수 있는 만큼, 우리의 것들에서 하나님의 것들을 이름 붙였기 때문이다. 그분이 자신만 아시는 이유로 우리에게 활동을 멈추고, 이를테면 관심을 두지 않으시는 것을 잠이라고 불렀다. 우리의 잠은 활동하지 않으며 아무 일도 하지 않는 상태이기 때문이다. 상태를 바꾸어 갑자기 선을 행하시는 것은 깨어남이라고 불렀다. 외면하다가 돌아보는 것처럼, 깨어남은 잠이 풀리는 것이기 때문이다. 우리는 벌하시는 일을 화내심이라고 표현했다. 우리에게는 벌하는 일이 분노에서 나오기 때문이다. 여기에서 활동하시다가 저기에서 활동하시는 일은 걸으심이라고 불렀다. 한곳에서 다른 곳으로 옮기는 일이 걸음이기 때문이다. 거룩한 권능들 안에서 쉬시며, 이를테면 즐겨 머무시는 일은 앉으심과 보좌에 오르심이라고 불렀다. 이것도 우리의 표현이다. 신적인 것은 거룩한 이들 안에서 어느 곳보다 편히 쉬기 때문이다. 빠른 움직임은 날아가심이라고 불렀다. 돌보심은 얼굴이라고 불렀다. 주심과 받아들이심은 손이라고 불렀다. 그 밖의 하나님의 능력과 활동도, 우리에게 다른 육체적 모습으로 그려졌다."
      },
