      "html_path": "works/gregory-nazianzus-oration-31/index.html#p-23",
      "label": "제5신학강론 (제31강론) 23",
      "location": "23",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:019f71e1074664d1597724f2ec3ff00d28b4e2951c6ad24d3a5982d448e460a3",
        "text": "Πάλιν σὺ πόθεν τὸ ἀγέννητον λαβὼν ἔχεις, ἢ τὸ ἄναρχον, τὰς σὰς ἀκροπόλεις, ἢ καὶ ἡμεῖς τὸ ἀθάνατον; δεῖξον ταῦτα ὀνομαστί, ἢ διαγράψομεν, καὶ τέθνηκας ἐκ τῶν σῶν ὑποθέσεων, καθαιρεθέντων σοι τῶν ὀνομάτων, καὶ τοῦ τείχους τῆς καταφυγῆς ἐφ’ ᾧ ἐπεποίθεις. ἢ δῆλον ὅτι ἐκ τῶν ταῦτα συναγόντων, κἂν μὴ ταῦτα λέγηται; τίνων τούτων; Ἐγώ εἰμι πρῶτος, καὶ ἐγὼ μετὰ ταῦτα. καί, Πρὸ ἐμοῦ οὐκ ἔστιν ἄλλος θεός, καὶ μετ’ ἐμὲ οὐκ ἔσται. ὅλον γὰρ τὸ ἔστιν ἐμόν· οὔτε ἠργμένον, οὔτε παυσόμενον. ταῦτα λαβών, τὸ μὲν μὴ εἶναί τι πρὸ αὐτοῦ, μηδὲ πρεσβυτέραν αἰτίαν ἔχειν, ἄναρχον προσηγόρευσας, καὶ ἀγέννητον· τὸ δὲ μὴ στήσεσθαι τοῦ εἶναι, ἀθάνατον καὶ ἀνώλεθρον. αἱ μὲν δὴ πρῶται συζυγίαι τοιαῦται, καὶ οὕτως ἔχουσαι. τίνα δὲ οὔτε ἔστιν, οὔτε λέγεται; πονηρὸν τὸ θεῖον, ἡ σφαῖρα τετράγωνος, τὸ παρελθὸν ἐνέστηκεν, οὐ σύνθετον ὁ ἄνθρωπος. τίνα γὰρ εἰς τοσοῦτόν ποτε ἐμπληξίας ἀφικόμενον ἔγνως, ὥστε τι τοιοῦτον ἢ ἐννοῆσαι τολμῆσαι, ἢ ἀποφήνασθαι; λείπεται δεῖξαι τίνα καὶ ἔστι καὶ λέγεται· θεός, ἄνθρωπος, ἄγγελος, κρίσις· ματαιότης οἱ τοιοῦτοι συλλογισμοί, καὶ τῆς πίστεως ἀνατροπή, καὶ τοῦ μυστηρίου κένωσις."
      },
      "title": "제5신학강론 (제31강론)",
      "translation": {
        "notes": [
          "태어나지 않음과 시작이 없음 등의 용어를 성경에 이름 그대로 제시하라는 질문을 상대에게 돌린다. 이사야 44:6과 43:10의 뜻에서 그런 용어들을 얻었다는 설명이다.",
          "앞의 두 짝은 실재와 표현이 일치하지 않는 두 경우를 가리킨다. 뒤에서는 실제로도 없고 말해지지도 않는 모순과, 실제로 있고 말해지기도 하는 것들을 구별한다."
        ],
        "revision_id": "sha256:dfa7928a3f6dd618c1c9eaec573560d4c3fad4c21cd08e571194d44157f25ebc",
        "text": "다시, 그대는 자신의 요새인 태어나지 않으심과 시작이 없으심을 어디서 얻었는가? 우리도 죽지 않으심을 어디서 얻었는가? 이것들을 그 이름 그대로 제시하라. 그렇지 않으면 지워 버리겠다. 그대가 의지한 이름들과 피신처의 성벽이 무너지면, 자신의 가정 때문에 그대는 죽었다. 그 이름들이 그대로 쓰이지 않더라도, 그런 결론을 이끄는 말들에서 얻었음이 분명하지 않은가? 어떤 말들인가? “나는 처음이며, 그 뒤에도 나다.” 또 “나보다 앞서 다른 하나님은 없으며, 내 뒤에도 없을 것이다.” ‘있다’라는 말 전체는 나의 것이며, 시작되지도 멈추지도 않는다. 그대는 이것들을 받아, 그분 앞에 아무것도 없고 더 앞선 원인도 없다는 사실을 시작이 없음과 태어나지 않음이라고 불렀다. 존재하심이 멈추지 않는다는 사실은 죽지 않음과 소멸하지 않음이라고 불렀다. 앞의 두 짝은 이와 같다. 실제로 있지도 않고 말해지지도 않는 것은 무엇인가? 신적인 것이 악하다는 말, 구가 네모라는 말, 과거가 현재라는 말, 인간이 합성되지 않았다는 말이다. 그런 무엇을 감히 생각하거나 선언할 만큼 미쳐 버린 사람을 그대는 본 적이 있는가? 실제로 있고 말해지기도 하는 것들을 밝히는 일이 남았다. 하나님, 인간, 천사, 심판이다. 이런 삼단논법들이 헛되며, 믿음을 무너뜨리고 신비를 헛되게 한다는 말도 그러하다."
      },
      "work_id": "gregory-nazianzus-oration-31",
      "work_passage_id": "gregory-nazianzus-oration-31:23"
