      "html_path": "works/athanasius-serapion-1/index.html#p-13",
      "label": "세라피온에게 보낸 제1서신 13",
      "location": "13",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:c35614587fc1dd5b2d198252eccc6effed1b6a12d9c2a79e6d007d52297e27ff",
        "text": "Ἀλλ’ ἔστω ταῦτα, φασι καὶ αὐτοί· διὰ τί οὖν ὁ Ἀπόστολος μετὰ τὸν Χριστὸν οὐκ ὠνόμασε τὸ Πνεῦμα τὸ ἅγιον, ἀλλὰ τοὺς ἐκλεκτοὺς ἀγγέλους; Τὸ αὐτὸ δ’ ἄν τις αὐτοὺς ἐρωτήσειε· Διὰ τί μὴ ἀρχαγγέλους, μηδὲ χερουβείμ, μηδὲ σεραφίμ, μηδὲ κυριότητας, μηδὲ θρόνους, μηδὲ ἕτερόν τι, ἀλλ’ ἐκλεκτοὺς μόνους ἀγγέλους ὠνόμασεν ὁ Παῦλος; Ἆρ’ οὖν, ἐπεὶ μὴ οὕτως ὠνόμασεν, οἱ ἄγγελοι ἀρχάγγελοι εἰσιν, ἢ μόνοι ἄγγελοι εἰσι, καὶ οὔτε σεραφίμ, ἢ χερουβείμ, οὐδ’ ἀρχάγγελοι, οὐδὲ κυριότητες, οὐ θρόνοι, οὐχ ἀρχαὶ, οὐχ ἕτερόν τι ἐστιν; Ἀλλὰ τοῦτό ἐστιν ἀνάγκην μὲν ἐπιβάλλειν τῷ Ἀποστόλῳ, διὰ τί μὴ οὕτως, ἀλλ’ οὕτως ἔγραψεν, ἀγνοεῖν δὲ τὰς θείας Γραφάς, καὶ διὰ τοῦτο πλανᾶσθαι περὶ τὴν ἀλήθειαν. Ἰδοὺ γὰρ παρὰ μὲν τῷ Ἠσαΐᾳ γέγραπται· « Προσαγάγετε πρὸς μέ, καὶ ἀκούσατε ταῦτα· Οὐχ ἀπ’ ἀρχῆς ἐν κρυφῇ λελάληκα· ἡνίκα ἐγένετο, ἐκεῖ ἤμην· καὶ νῦν Κύριος ἀπέσταλκέ με, καὶ τὸ Πνεῦμα αὐτοῦ· » παρὰ δὲ τῷ Ἀγγαίῳ· « Καὶ νῦν κατίσχυε Ζοροβάβελ, λέγει Κύριος, καὶ κατίσχυε Ἰησοῦ ὁ τοῦ Ἰωσεδὲκ, ὁ ἱερεὺς ὁ μέγας, λέγει Κύριος. Καὶ κατισχυέτω πᾶς ὁ λαὸς τῆς γῆς, λέγει Κύριος· καὶ ποιεῖτε, διότι μεθ᾿ ὑμῶν ἐγὼ εἰμι, λέγει Κύριος παντοκράτωρ, καὶ τὸ Πνεῦμά μου ἐφέστηκεν ἐν μέσῳ ὑμῶν. » Καὶ παρ᾿ ἀμφοτέροις τοῖς προφήταις περὶ μόνου τοῦ Κυρίου καὶ τοῦ Πνεύματος μνήμη γέγονε. Τί τοίνυν καὶ περὶ τούτου φήσουσιν; Εἰ γάρ, ἐπειδὴ τοῦ Χριστοῦ μνημονεύσας ὁ Παῦλος περὶ μὲν τοῦ Πνεύματος ἐσιώπησεν, τῶν δὲ ἐκλεκτῶν ἀγγέλων ἐμνημόνευσεν, διὰ τοῦτο ἐν ἀγγέλοις τὸ Πνεῦμα συντάττουσιν· ὥρα, καὶ τοῖς προφητικοῖς τούτοις ἐντυχάνοντας, τολμηρότερον αὐτοὺς διαλογιζέσθαι καὶ περὶ τοῦ σεσιωπημένου. Ἄν τε γὰρ τὸν Κύριον εἶναι, φήσουσιν εἶναι τὸν Υἱόν, τί ἂν εἴποιεν περὶ τοῦ Πατρός; Ἄν τε τὸν Πατέρα εἴπωσι, τί ἂν εἴποιεν περὶ τοῦ Υἱοῦ; Τὴν γὰρ ἀκολουθοῦσαν κατ᾿ ἐκείνους δυσφημίαν μηδὲ λογίσασθαι τινὰ γένοιτο· ἀνάγκη γὰρ αὐτοὺς εἰπεῖν, ἢ ὅτι οὐκ ἔστιν, ἢ τοῖς ποιήμασι συναριθμεῖν τὸ σεσιωπημένον."
      },
      "title": "세라피온에게 보낸 제1서신",
      "translation": {
        "notes": [
          "어떤 구절에 이름이 없다는 사실로 그분의 존재나 본성을 정하면, 주님과 성령만 언급되는 예언서에서 아버지나 아들을 피조물로 보아야 하는 모순이 생긴다.",
          "딤전 5:21의 천사 언급을 사 48:16과 학 2:4-5에 대조한다. 두 예언서의 인용에서는 주님과 성령의 언급 여부에 초점을 둔다."
        ],
        "revision_id": "sha256:c6222441b2b85399943a6cd7ad81fb04937499fe236b4beb6b024b459382b3f8",
        "text": "그러나 그들 자신도 말합니다. “그 점은 인정하자. 그렇다면 왜 사도는 그리스도 뒤에 성령을 언급하지 않고, 택함 받은 천사들을 언급했는가?” 누군가 그들에게도 같은 질문을 할 수 있을 것입니다. 바울은 왜 대천사도, 그룹도, 스랍도, 주권들도, 보좌들도, 다른 무엇도 언급하지 않고, 택함 받은 천사들만 언급했습니까? 그러면 그가 그렇게 언급하지 않았다는 이유로, 천사들이 곧 대천사입니까? 아니면 천사들만 있고, 스랍이나 그룹이나 대천사도 없으며, 주권들이나 보좌들이나 권세들이나 다른 어떤 것도 없습니까? 이런 주장은 사도에게 강요하면서, 왜 저렇게 쓰지 않고 이렇게 썼느냐고 따지는 것입니다. 또 성경을 알지 못하여, 그 때문에 진리에서 벗어나는 것입니다. 보십시오. 이사야에는 이렇게 기록되어 있습니다. “내게 가까이 와서 이 말을 들어라. 나는 처음부터 은밀히 말하지 않았다. 그 일이 일어났을 때 내가 거기에 있었다. 이제 주께서 나를 보내셨고, 그의 영도 보내셨다.” 학개에는 이렇게 말합니다. “이제 힘을 내어라, 스룹바벨아. 주께서 말씀하신다. 힘을 내어라, 여호사닥의 아들 대제사장 여호수아야. 주께서 말씀하신다. 이 땅의 모든 백성도 힘을 내어라. 주께서 말씀하신다. 그리고 일을 하여라. 내가 너희와 함께 있기 때문이다. 주 만군의 하나님께서 말씀하신다. 내 영이 너희 가운데 서 있다.” 두 예언자 모두에게서 주님과 성령만 언급되었습니다. 그러면 그들은 이것에 관해서는 무슨 말을 하겠습니까? 바울이 그리스도를 언급한 뒤, 성령에 관해서는 침묵하고 택함 받은 천사들을 언급했다는 이유로, 그들이 성령을 천사들 가운데 넣는다면, 이제는 이 예언자들의 말씀을 읽고서도, 언급되지 않은 분에 관해 더욱 무모하게 추론할 차례입니다. 만일 여기의 주님을 아들이라고 한다면, 아버지에 관해서는 무엇이라고 하겠습니까? 아버지라고 한다면, 아들에 관해서는 무엇이라고 하겠습니까? 그들의 주장에 따라오는 모독을 누구도 생각하는 일이 없기를 바랍니다. 그들은 언급되지 않은 분이 존재하지 않는다고 하거나, 그를 지음 받은 것들 가운데 셈할 수밖에 없기 때문입니다."
      },
      "work_id": "athanasius-serapion-1",
      "work_passage_id": "athanasius-serapion-1:13"
