      "html_path": "works/athanasius-serapion-2/index.html#p-7",
      "label": "세라피온에게 보낸 제2서신 7",
      "location": "7",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:604298878cb9714ba513f099ff0beb351af90b199ea74f74a311e8c328e03833",
        "text": "Ἀλλ’ ἐπειδὴ προφασίζονται τὸ ἐν ταῖς Παροιμίαις γεγραμμένον τὸ, « Κύριος ἔκτισέ με ἀρχὴν ὁδῶν αὐτοῦ εἰς ἔργα αὐτοῦ, » καὶ ἐπιλέγουσιν ἑαυτοῖς: Ἰδοὺ ἔκτισε, καὶ κτίσμα ἐστίν· ἀναγκαῖόν ἐστι καὶ ἐκ τούτου δεῖξαι ὅσον πλανῶνται, μὴ εἰδότες τὸν σκοπὸν τῆς θείας Γραφῆς. Εἰ μὲν οὖν Υἱός ἐστι, μὴ λεγέσθω κτίσμα· εἰ δὲ κτίσμα, μὴ λεγέσθω Υἱός. Δέδεικται γὰρ ἐν τοῖς ἔμπροσθεν, ὅση διαφορά ἐστι κτίσματος καὶ Υἱοῦ. Καὶ ἐπειδή ἡ τελείωσις οὐκ εἰς κτίστην καὶ κτίσμα ἀλλ᾽ εἰς Πατέρα καὶ Υἱὸν κρατεῖ, ἀνάγκη μὴ λέγεσθαι κτίσμα, ἀλλ᾽ Υἱὸν τὸν Κύριον. Οὐ γέγραπται οὖν; φησί. Ναὶ γέγραπται, καὶ ἀναγκαίως εἴρηται· ἀλλὰ κακῶς νοοῦσι τὸ καλῶς εἰρημένον οἱ αἱρετικοί. Εἰ γὰρ ἐνόουν καὶ ἐγνώσκον τὸν χαρακτῆρα τοῦ Χριστιανισμοῦ, οὐκ ἂν τὸν Κύριον τῆς δόξης ἔλεγον κτίσμα εἶναι, οὐδὲ προσέκοπτον τῷ γεγραμμένῳ καλῶς. Ἐκεῖνοι μὲν οὖν « οὐκ ἔγνωσαν, οὐδὲ συνῆκαν· », διὰ τοῦτο, ὡς γέγραπται, « ἐν σκότει διαπορεύονται· » ἡμᾶς δὲ ὅμως ἀναγκαῖον εἰπεῖν, ἵν’ ἐκεῖνοι μὲν καὶ ἐν τούτῳ δειχθῶσιν ἄφρονες, ἡμεῖς δὲ μὴ παραλίπωμεν τὸν κατὰ τῆς ἀσεβείας αὐτῶν ἔλεγχον, ἵσως καὶ αὐτοὶ μεταγνώσιν. Ὁ χαρακτὴρ τοίνυν τῆς ἐν Χριστῷ πίστεως ἐστὶν οὗτος, τὸν Υἱὸν τοῦ Θεοῦ, Λόγον ὄντα Θεὸν (« Ἐν ἀρχῇ γὰρ ὁ Λόγος, καὶ Θεὸς ἦν ὁ Λόγος »), σοφίαν ὄντα καὶ δύναμιν τοῦ Πατρός, (Χριστὸς γὰρ Θεοῦ δύναμις καὶ Θεοῦ σοφία), τοῦτον ἐπὶ συντελείᾳ τῶν αἰώνων ἄνθρωπον γενέσθαι διὰ τὴν ἡμετέραν σωτηρίαν. Αὐτὸς γὰρ ὁ Ἰωάννης, εἰρηκώς, « Ἐν ἀρχῇ ἦν ὁ Λόγος, » μετ’ ὀλίγα εἶπε· « καὶ ὁ Λόγος σὰρξ ἐγένετο· » ἴσον τῷ εἰπεῖν, ἄνθρωπος γέγονε. Καὶ ὁ μὲν Κύριος περὶ ἑαυτοῦ ἔλεγε· « Τί με ζητεῖτε ἀποκτεῖναι, ἄνθρωπον ὃς τὴν ἀλήθειαν ὑμῖν λελάληκα; » ὁ δὲ Παῦλος, παρ᾽ αὐτοῦ μαθὼν, ἔλεγε· « Εἷς Θεὸς, εἷς καὶ μεσίτης Θεοῦ καὶ ἀνθρώπων, ἄνθρωπος Χριστὸς Ἰησοῦς· » ἄνθρωπος δὲ γενόμενος καὶ οἰκονομήσας τὰ ἀνθρώπινα, τροπώσας τε καὶ καταργήσας τὸν καθ᾽ ἡμῶν θάνατον, κάθηται νῦν ἐν δεξιᾷ τοῦ Πατρός, ἐν αὐτῷ ὤν, καὶ τοῦ Πατρὸς ὄντος ἐν αὐτῷ, ὡσπερ ἦν ἀεί, καὶ ἐστι διαπαντός."
      },
      "title": "세라피온에게 보낸 제2서신",
      "translation": {
        "notes": [
          "잠 8:22의 ‘창조하셨다’를 해석하기 위해 그리스도교 신앙의 특징을 제시한다. 하나님이신 말씀이 구원을 위해 사람이 되셨다는 고백이 이 해석의 기준이다.",
          "요 1:1과 1:14, 요 8:40, 딤전 2:5가 연결된다. 인간으로 오신 뒤에도 아들이 아버지 안에 계시는 관계는 지속된다고 설명한다."
        ],
        "revision_id": "sha256:16a28ae0b82bb287e0346ac189e563301fe25e454eb3106e8e0b12117195f644",
        "text": "그러나 그들은 잠언에 기록된 다음 말씀을 구실로 삼습니다. “주께서 자기 일을 위하여 나를 자기 길의 시작으로 창조하셨다.” 그들은 자기들끼리 덧붙입니다. “보라, 창조하셨으므로 그는 피조물이다.” 그러므로 이 말씀에서도 그들이 얼마나 잘못 생각하는지 밝혀야 합니다. 그들은 성경의 목적을 알지 못합니다. 그가 아들이시라면, 피조물이라고 부르지 말아야 합니다. 피조물이라면, 아들이라고 부르지 말아야 합니다. 피조물과 아들 사이의 차이가 얼마나 큰지는 앞서 밝혀졌습니다. 또 완성은 창조주와 피조물이 아니라 아버지와 아들을 향해 이루어지므로, 주님을 피조물이라고 부르지 않고, 아들이라고 불러야 합니다. 그들은 묻습니다. “그러면 그렇게 기록되어 있지 않은가?” 그렇습니다. 기록되어 있으며, 그렇게 말씀하실 필요도 있었습니다. 그러나 이단자들은 올바르게 말씀하신 것을 잘못 이해합니다. 그들이 그리스도교의 특징을 이해하고 알았다면, 영광의 주님을 피조물이라고 말하지 않았을 것이고, 올바르게 기록된 말씀에 걸려 넘어지지도 않았을 것입니다. 그들은 “알지도 못했고 깨닫지도 못했습니다.” 그러므로 기록되었듯이 “어둠 속을 걸어 다닙니다.” 그러나 우리는 말해야 합니다. 이 일에서도 그들의 어리석음이 드러나고, 우리가 그들의 불경함을 반박하는 일을 빠뜨리지 않도록 해야 합니다. 그들 자신도 생각을 바꿀지 모릅니다. 그리스도 안의 신앙이 지니는 특징은 다음과 같습니다. 하나님의 아들은 말씀이시며 하나님이십니다. (“태초에 말씀이 계셨으며, 말씀은 하나님이셨기 때문입니다.”) 아들은 아버지의 지혜이자 능력이십니다. (그리스도는 하나님의 능력이자 하나님의 지혜이시기 때문입니다.) 그가 시대들의 마지막에 사람이 되셨습니다. 우리의 구원을 위해 그렇게 되셨습니다. 요한 자신은 “태초에 말씀이 계셨다”라고 말한 뒤, 조금 뒤에 말했습니다. “말씀이 육신이 되셨다.” 그가 사람이 되셨다는 말과 같은 뜻입니다. 주님은 자신에 관해 말씀하셨습니다. “왜 너희는 나를 죽이려 하느냐? 너희에게 진리를 말한 사람인 나를 말이다.” 바울은 그에게서 배워 말했습니다. “하나님은 한 분이시며, 하나님과 사람들 사이의 중재자도 한 분이십니다. 그는 사람이신 그리스도 예수이십니다.” 그는 사람이 되시고 사람에게 속한 일들을 이루셨으며, 우리를 거스르는 죽음을 물리치고 없애셨습니다. 이제 아버지의 오른편에 앉아 계시며, 아버지 안에 계시고, 아버지도 아들 안에 계십니다. 언제나 그러하셨으며 영원히 그러하십니다."
      },
