      "html_path": "works/athanasius-serapion-2/index.html#p-8",
      "label": "세라피온에게 보낸 제2서신 8",
      "location": "8",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:1de4e8ddf8623763b0f1591e4010a1a01f5e34e32a0c1d72c6d9fd75c9523a28",
        "text": "Ὁ μὲν χαρακτὴρ οὗτος ἐκ τῶν ἀποστόλων διὰ τῶν Πατέρων δεῖ δὲ λοιπόν, ἐντυγχάνοντα τῇ Γραφῇ, δοκιμάζειν καὶ διακρίνειν, πότε μὲν περὶ τῆς θεότητος τοῦ Λόγου λέγει, πότε δὲ περὶ τῶν ἀνθρωπίνων αὐτοῦ· ἵνα μὴ ἕτερα ἀνθ’ ἑτέρων νοοῦντες παραπαίωμεν, ἃ πεπόνθασιν οἱ Ἀρειανοί. Ὥσπερ τοίνυν, Λόγον αὐτὸν εἰδότες, οἴδαμεν, ὅτι δι’ αὐτοῦ τὰ πάντα ἐγένετο, καὶ χωρὶς αὐτοῦ ἐγένετο οὐδὲ ἕν· καὶ, Τῷ Λόγῳ Κυρίου οἱ οὐρανοὶ ἐστερεώθησαν· καὶ, Ἀποστέλλει τὸν Λόγον αὐτοῦ, καὶ ἰάται τὰ πάντα· καὶ σοφίαν δὲ αὐτὸν εἰδότες, οἴδαμεν, ὅτι ὁ Θεὸς τῇ σοφίᾳ ἐθεμελίωσεν τὴν γῆν, καὶ πάντα ἐν σοφίᾳ ἐποίησεν ὁ Πατὴρ· καὶ Θεὸν δὲ αὐτὸν εἰδότες, πεπιστεύκαμεν, ὅτι αὐτός ἐστιν ὁ Χριστός· « Ὁ θρόνος σου » γὰρ, ᾄδει Δαβὶδ, « ὁ Θεὸς, εἰς αἰῶνα αἰῶνος· ῥάβδος εὐθύτητος ἡ ῥάβδος τῆς βασιλείας σου. Ἡγάπησας δικαιοσύνην, καὶ ἐμίσησας ἀδικίαν· διὰ τοῦτο ἔχρισέ σε ὁ Θεός, ὁ Θεός σου, ἔλαιον ἀγαλλιάσεως παρὰ τοὺς μετόχους σου. » Καὶ ἐν μὲν τῷ Ἠσαΐᾳ αὐτὸς περὶ ἑαυτοῦ λέγει· « Πνεῦμα Κυρίου ἐπ’ ἐμὲ, οὗ εἵνεκεν ἔχρισέ με. » Ὁ δὲ Πέτρος ὁμολόγησεν, ὅτι « Σὺ εἶ ὁ Χριστὸς ὁ Υἱὸς τοῦ Θεοῦ τοῦ ζῶντος· » οὕτως εἰδότες αὐτὸν ἄνθρωπον γενόμενον, οὐκ ἀρνοῦμεθα τὰ περὶ αὐτοῦ ἀνθρωπίνως λεγόμενα, οἷά ἐστι τὸ πεινᾶν, τὸ διψᾶν, τὸ ραπισθῆναι, τὸ δακρῦσαι, τὸ κοιμηθῆναι, καὶ τέλος τῷ σταυρῷ ἀναδέξασθαι τὸν ὑπὲρ ἡμῶν θάνατον· ταῦτα γὰρ πάντα περὶ αὐτοῦ γέγραπται. Οὕτως καὶ τὸ, « ἔκτισεν, » ἀνθρώποις ἁρμόδιον οὐκ ἀπέκρυψεν ἡ Γραφὴ, ἀλλ’ εἴρηκεν. Ἐκτίσθημεν γὰρ καὶ πεποιήμεθα οἱ ἄνθρωποι. Ἀλλ’ ὡσπερ ἀκούοντες, ἐπείνασεν, ἐκοιμήθη, ἐρραπίσθη, οὐκ ἀρνοῦμεθα αὐτοῦ τὴν θεότητα· οὕτως ἀκούοντες τὸ, « ἔκτισεν, » ἀκόλουθον ἂν εἴη μνημονεύειν, ὅτι, Θεὸς ὢν, ἐκτίσθη ἄνθρωπος. Ἀνθρώπων γὰρ ἴδιον τὸ κτίζεσθαι, ὡσπερ καὶ τὰ προειρημένα, τὸ πεινᾶν, καὶ τὰ ὁμοία."
      },
      "title": "세라피온에게 보낸 제2서신",
      "translation": {
        "notes": [
          "성경이 말씀의 신성과 그가 취하신 인간적인 일들 중 무엇을 말하는지 구별하라고 권한다. 배고픔, 목마름, 눈물, 잠, 고난을 신성의 부정으로 읽지 않는 것처럼 ‘창조하셨다’도 성육신의 문맥에서 해석한다.",
          "‘하나님이시면서 사람으로 창조되셨다’는 이 절의 표현은 말씀이 취하신 인성을 가리킨다. 아들의 신적 본질과 인간으로 오신 일을 구별하는 앞선 논증에 따른다."
        ],
        "revision_id": "sha256:6723021e658cc228ff5d1183b142776885654b0a57f9d606e75f84107425b69a",
        "text": "이 특징은 사도들에게서 교부들을 통해 전해졌습니다. 그러므로 성경을 읽는 이는 살피고 구별해야 합니다. 언제 말씀의 신성에 관해 말하는지, 언제 그의 인간적인 것들에 관해 말하는지 구별해야 합니다. 서로 다른 것을 혼동하여 그릇된 길에 빠지지 않도록 해야 합니다. 아리우스파가 그런 일을 겪었습니다. 우리는 그가 말씀이심을 알기에, 만물이 그를 통해 생겨났으며, 그 없이 생겨난 것은 하나도 없다는 것을 압니다. 또 ‘주의 말씀으로 하늘들이 굳게 세워졌다’는 것을 압니다. 또 ‘그는 자기 말씀을 보내셔서 모든 것을 고치신다’는 것을 압니다. 그가 지혜이심을 알기에, 하나님께서 지혜로 땅의 기초를 놓으셨으며, 아버지가 모든 것을 지혜로 만드셨다는 것을 압니다. 그가 하나님이심을 알기에, 우리는 그가 그리스도이심을 믿습니다. 다윗은 이렇게 노래합니다. “주의 보좌는, 하나님이여, 영원합니다. 주의 나라의 홀은 올바름의 홀입니다. 주는 의를 사랑하고, 불의를 미워하셨습니다. 그러므로 하나님, 곧 주의 하나님께서 주께 기름을 부으셨습니다. 주와 함께하는 이들보다 더 많은 기쁨의 기름을 부으셨습니다.” 이사야에서 그는 자신에 관해 말씀하십니다. “주의 영이 내 위에 계신다. 그가 내게 기름을 부으셨기 때문이다.” 베드로는 고백했습니다. “주는 그리스도이시며 살아 계신 하나님의 아들이십니다.” 그와 같이 우리는 그가 사람이 되셨음을 알기에, 그에 관해 인간의 방식으로 말한 것들을 부인하지 않습니다. 배고파하심과 목말라하심, 뺨 맞으심과 눈물 흘리심, 잠드심, 마지막으로 십자가에서 우리를 위한 죽음을 받아들이심과 같은 것들입니다. 이 모든 것은 그에 관해 기록되어 있습니다. 그와 같이 성경은 사람에게 적합한 “창조하셨다”는 표현도 숨기지 않고, 말했습니다. 우리 사람들은 창조되고 만들어졌기 때문입니다. 우리는 그가 배고파하시고 잠드시고 뺨 맞으셨다는 말을 들어도, 그의 신성을 부인하지 않습니다. 그와 같이 “창조하셨다”는 말을 들으면, 다음 사실을 기억하는 것이 마땅합니다. 그는 하나님이시면서 사람으로 창조되셨습니다. 창조되는 것은 사람들에게 고유한 일이기 때문입니다. 앞서 말한 배고픔과 그와 비슷한 일들도 그러합니다."
      },
