      "html_path": "works/athanasius-serapion-2/index.html#p-9",
      "label": "세라피온에게 보낸 제2서신 9",
      "location": "9",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:e50b878b4af74e680b61b2a8adeb3d6597d39a71c8eee38a16ec2684c17beccd",
        "text": "Καὶ γὰρ κάκεινο πάλιν τὸ καλῶς μὲν εἰρημένον, κακῶς δὲ νοούμενον παρ’ αὐτοῖς· φημὶ δὴ τὸ, « Περὶ τῆς ἡμέρας ἢ τῆς ὥρας ἐκείνης οὐδεὶς οἶδεν, οὐδὲ οἱ ἄγγελοι, οὐδὲ ὁ Υἱός, » καλὸν ἔχει τὸν νοῦν. Ἐκεῖνοι μὲν γὰρ νομίζουσιν ἐκ τοῦ λέγειν, « οὐδὲ ὁ Υἱός, » ὅτι ἀγνοοῦν δηλοῖ, ὅτι κτίσμα ἐστίν. Οὐχ ἔστι δὲ οὕτως· μὴ γένοιτο! καὶ γὰρ ὡσπερ λέγων, « Ἔκτισέ με, » ἀνθρωπίνως εἴρηκεν· οὕτως λέγων, « οὐδὲ ὁ Υἱὸς, » ἀνθρωπινῶς εἴρηκε. Καὶ τὸ αἴτιον τοῦ οὕτως εἰρηκέναι ἔχει τὸ εὔλογον. Ἐπειδή γὰρ ἄνθρωπος γέγονεν, ὡς γέγραπται, ἀνθρώπων δὲ ἴδιον τὸ ἀγνοεῖν, ὥσπερ καὶ τὸ πεινᾶν, καὶ τὰ ἄλλα (οὐ γὰρ γινώσκουσιν, ἐὰν μὴ ἀκούσωσι καὶ μάθωσι), διὰ τοῦτο καὶ τὴν ἄγνοιαν τῶν ἀνθρώπων, ὡς ἄνθρωπος γεγονὼς, ἐπιδείκνυται· πρῶτον μὲν, ἵνα δεῖξῃ, ὅτι ἀληθῶς ἀνθρώπινον ἔχει σῶμα· ἔπειτα δέ, ἵνα καὶ, τὴν ἄγνοιαν τῶν ἀνθρώπων ἐν τῷ σώματι ἔχων, ἀπὸ πάντων λυτρωσάμενος καὶ καθαρίσας, τελείαν καὶ ἁγίαν παραστήσῃ τῷ Πατρὶ τὴν ἀνθρωπότητα. Ποίαν ἔτι πρόφασιν εὑρήσουσιν οἱ Ἀρειανοί; Τί λοιπόν ἐπινόησαντες γογγύσουσι; Κατεγνώσθησαν μὴ εἰδότες τὸ, « Κύριος ἔκτισέ με εἰς ἔργα αὐτοῦ. » Καὶ ἐδείχθησαν μὴ νοοῦντες τὸ, « Περὶ δὲ τῆς ἡμέρας ἐκείνης οὐδεὶς οἶδεν, οὐδὲ οἱ ἄγγελοι, οὐδὲ ὁ Υἱός. » Καὶ γὰρ ὡσπερ λέγων μὲν τὸ, « ἔκτισε, » τὸ ἀνθρώπινον σημαίνει, ὅτι ἄνθρωπος γέγονε καὶ ἐκτίσθη· λέγων δὲ, « Ἐγὼ καὶ ὁ Πατὴρ ἕν ἐσμεν, » καὶ, « Ὁ ἑωρακὼς ἐμὲ ἑώρακε τὸν Πατέρα, » καὶ, « Ἐγὼ ἐν τῷ Πατρὶ, καὶ ὁ Πατὴρ ἐν ἐμοὶ, » τὴν ἀϊδιότητα καὶ τὸ πρὸς τὸν Πατέρα ὁμοούσιον σημαίνει· οὕτως λέγων, « Οὐδεὶς οἶδεν, οὐδὲ ὁ Υἱὸς, » ὡς ἄνθρωπος πάλιν λέγει· ἀνθρώπων γὰρ ἴδιον τὸ ἀγνοεῖν. Λέγων δὲ, « Οὐδεὶς οἶδε τὸν Πατέρα εἰ μὴ ὁ Υἱὸς, οὐδὲ τὸν Υἱὸν εἰ μὴ ὁ Πατὴρ, » οἶδε πολλῷ πλέον τὰ γεννητά. Οἱ μὲν οὖν μαθηταὶ ἐν τῷ κατὰ Ἰωάννην ἔλεγον τῷ Κυρίῳ· « Νῦν οἴδαμεν, ὅτι πάντα οἶδας. » Εὔδηλον οὖν, ὅτι οὐδὲν ἐστιν ὃ ἀγνοεῖ, Λόγος ὢν, δι’ οὗ τὰ πάντα ἐγένετο. Τῶν δὲ πάντων οὖσα καὶ ἡ ἡμέρα ἐκείνη, πάντως δι’ αὐτοῦ γενήσεται, κἂν διαρραγῶσι μυριάκις τῇ ἑαυτῶν ἀγνοίᾳ οἱ Ἀρειανοί."
      },
      "title": "세라피온에게 보낸 제2서신",
      "translation": {
        "notes": [
          "막 13:32의 ‘아들도 모른다’는 말씀을 참된 인성과 연결한다. 아타나시우스는 사람의 알지 못함을 아들이 받아들이신 일과, 그 인성을 완전하고 거룩하게 하여 아버지께 바치시는 일을 함께 설명한다.",
          "요한복음의 아버지와 아들의 관계, 마 11:27의 상호 지식, 요 16:30의 ‘모든 것을 아신다’는 고백이 대조된다. 만물을 통해 존재하게 하시는 말씀이 그 만물에 속한 마지막 날도 아신다고 결론 내린다."
        ],
        "revision_id": "sha256:d085c3c088d38a72d8f8c9d5bf0acf220ac04b610f33f2f829a72dbf33171131",
        "text": "또 올바르게 말씀하셨는데도 그들이 잘못 이해하는 다른 말씀도, 곧 다음 말씀도, “그날이나 그때에 관해서는 아무도 모르며, 천사들도 아들도 모른다”는 말씀도, 올바른 의미를 지닙니다. 그들은 “아들도 모른다”는 말씀에서, 아들이 알지 못한다는 사실이 드러나므로, 피조물이라고 생각합니다. 그러나 그렇지 않습니다. 그런 생각조차 없기를 바랍니다! “나를 창조하셨다”라고 말씀하실 때, 인간의 방식으로 말씀하셨듯이, “아들도 모른다”라고 말씀하실 때에도, 인간의 방식으로 말씀하셨습니다. 그렇게 말씀하신 데에는 합당한 이유가 있습니다. 기록되었듯이 그는 사람이 되셨고, 사람들에게는 알지 못함이 고유합니다. 배고픔과 다른 일들도 그렇습니다. (사람은 듣고 배우지 않으면 알지 못하기 때문입니다.) 그러므로 그는 사람들의 알지 못함도, 사람이 되신 분으로서 드러내십니다. 먼저 참으로 사람의 몸을 지니셨음을 밝히려는 것입니다. 또 사람들의 알지 못함을 몸 안에 지니신 채, 모든 것에서 구속하고 깨끗하게 하여, 인성을 완전하고 거룩하게 하여 아버지께 바치려는 것입니다. 아리우스파는 또 무슨 구실을 찾겠습니까? 이제 무엇을 만들어 내어 불평하겠습니까? 그들은 다음 말씀을 알지 못한다는 이유로 정죄받았습니다. “주께서 자기 일을 위하여 나를 창조하셨다.” 또 다음 말씀을 이해하지 못한다는 것이 드러났습니다. “그날에 관해서는 아무도 모르며, 천사들도 아들도 모른다.” 그가 “창조하셨다”라고 말씀하실 때, 인간적인 것을 가리키십니다. 사람이 되시고 창조되셨다는 뜻입니다. 그러나 다음과 같이 말씀하실 때, “나와 아버지는 하나이다.” “나를 본 이는 아버지를 보았다.” “나는 아버지 안에 있고, 아버지는 내 안에 계신다.” 그는 영원하심과 아버지와의 동일본질을 가리키십니다. 그와 같이 “아무도 모르며 아들도 모른다”라고 말씀하실 때, 다시 사람으로서 말씀하십니다. 알지 못함은 사람들에게 고유하기 때문입니다. 그러나 다음과 같이 말씀하실 때, “아들 외에는 아무도 아버지를 알지 못하며, 아버지 외에는 아무도 아들을 알지 못한다.” 그는 생겨난 것들을 훨씬 더 잘 아십니다. 요한복음에서 제자들은 주님께 말했습니다. “이제 우리는 주께서 모든 것을 아신다는 것을 압니다.” 그러므로 아들이 알지 못하시는 것이 전혀 없다는 것은 분명합니다. 그는 말씀이시며, 만물은 그를 통해 생겨났습니다. 그날도 만물 가운데 속하므로, 반드시 아들을 통해 올 것입니다. 아리우스파가 자기들의 무지 때문에 만 번 찢어져도 그러할 것입니다."
      },
