        "text": "Τίς οὖν ἄν, τίς ἐξαριθμήσειε τὸν πατέρα, ἵνα καὶ τοῦ λόγου τούτου τὰς δυνάμεις ἐξεύροι; ἔστι γὰρ ὥσπερ τοῦ πατρὸς λόγος καὶ σοφία, οὕτω καὶ τοῖς γενητοῖς συγκαταβαίνων, γίνεται πρὸς τὴν τοῦ γεννήτορος γνῶσιν καὶ ἔννοιαν αὐτοαγιασμὸς καὶ αὐτοζωὴ καὶ θύρα καὶ ποιμὴν καὶ ὁδὸς καὶ βασιλεὺς καὶ ἡγεμὼν καὶ ἐπὶ πᾶσι σωτὴρ καὶ ζωοποιὸς καὶ φῶς καὶ πρόνοια τῶν πάντων. τοιοῦτον ἄρα ἀγαθὸν καὶ δημιουργὸν υἱὸν ἔχων ἐξ ἑαυτοῦ ὁ πατήρ, οὐκ ἀφανῆ αὐτὸν τοῖς γενητοῖς ἀπέκρυψεν, ἀλλὰ καὶ ὁσημέραι τοῦτον ἀποκαλύπτει τοῖς πᾶσι διὰ τῆς τῶν πάντων δι’ αὐτοῦ συστάσεως καὶ ζωῆς. ἐν αὐτῷ δὲ καὶ δι’ αὐτοῦ καὶ ἑαυτὸν ἐμφαίνει, καθὼς ὁ σωτήρ φησιν· ἐγὼ ἐν τῷ πατρὶ καὶ ὁ πατὴρ ἐν ἐμοί. ὥστε ἐξ ἀνάγκης εἶναι τὸν λόγον ἐν τῷ γεννήσαντι καὶ τὸν γεννηθέντα σὺν τῷ πατρὶ διαιωνίζειν. τούτων δὲ οὕτως ἐχόντων καὶ οὐδενὸς ἔξωθεν αὐτοῦ τυγχάνοντος, ἀλλὰ καὶ οὐρανοῦ καὶ γῆς καὶ πάντων τῶν ἐν αὐτοῖς ἐξηρτημένων αὐτοῦ, ὅμως ἄνθρωποι παράφρονες, παραγκωνισάμενοι τὴν πρὸς τοῦτον γνῶσιν καὶ εὐσέβειαν, τὰ οὐκ ὄντα πρὸ τῶν ὄντων ἐτίμησαν καὶ ἀντὶ τοῦ ὄντως ὄντος θεοῦ τὰ μὴ ὄντα ἐθεοποίησαν, τῇ κτίσει παρὰ τὸν κτίσαντα λατρεύοντες, πρᾶγμα πάσχοντες ἀνόητον καὶ δυσσεβές. ὅμοιον γὰρ ὡς εἴ τις τὰ ἔργα πρὸ τοῦ τεχνίτου θαυμάσειε καὶ τὰ ἐν τῇ πόλει δημιουργήματα καταπλαγείς, τὸν τούτων δημιουργὸν καταπατοίη. ἢ ὡς εἴ τις τὸ μὲν μουσικὸν ὄργανον ἐπαινοίη, τὸν δὲ συνθέντα καὶ ἁρμοσάμενον ἐκβάλλοι. ἄφρονες καὶ πολὺ τὸν ὀφθαλμὸν πεπηρωμένοι. πῶς γὰρ ἂν ἔγνωσαν ἄλλως οἰκοδομὴν ἢ ναῦν ἢ λύραν, μὴ οὐχὶ τοῦ ναυπηγοῦ ἐργασαμένου καὶ τοῦ ἀρχιτέκτονος οἰκοδομήσαντος καὶ τοῦ μουσικοῦ συνθέντος; ὥσπερ οὖν ὁ ταῦτα λογιζόμενος μαίνεται καὶ ὑπερέκεινα πάσης μανίας ἐστίν, οὕτως οὔ μοι δοκοῦσιν ὑγιαίνειν τὴν διάνοιαν, οἱ τὸν θεὸν μὴ ἐπιγινώσκοντες, καὶ τὸν τούτου λόγον μὴ θρησκεύοντες τὸν σωτῆρα τῶν πάντων τὸν κύριον ἡμῶν Ἰησοῦν Χριστόν, δι’ οὗ τὰ πάντα ὁ πατὴρ διακοσμεῖ καὶ συνέχει καὶ προνοεῖται τῶν ὅλων. εἰς ὃν σὺ τὴν πίστιν ἔχων καὶ τὸ θεοσεβές, ὦ φιλόχριστε, χαῖρε καὶ εὔελπις γίνου, ὅτι τῆς εἰς αὐτὸν πίστεως καὶ εὐσεβείας, ἀθανασία καὶ βασιλεία οὐρανῶν ἐστιν ὁ καρπός, μόνον ἐὰν κατὰ τοὺς αὐτοῦ νόμους ἡ ψυχὴ κεκοσμημένη γένηται. ὥσπερ γὰρ τοῖς κατ’ αὐτὸν πολιτευομένοις ἐστὶ τὸ ἔπαθλον ζωὴ αἰώνιος, οὕτως τοῖς τὴν ἐναντίαν καὶ μὴ τὴν τῆς ἀρετῆς ἀτραπὸν ὁδεύουσιν, αἰσχύνη μεγάλη καὶ κίνδυνος ἀσύγνωστος ἐν ἡμέρᾳ κρίσεως, ὅτι καίτοι γνόντες τὴν τῆς ἀληθείας ὁδόν, ἐναντία ὧν ἔγνωσαν ἔπραξαν."
