      "title": "이방인 논박",
      "translation": {
        "notes": [
          "아버지와 아들의 상호 내주에 관한 인용은 요한복음 14:10-11이다. 문·목자·길 등의 호칭을 나열하는 문장은 각각의 성경 구절 번호가 없는 저자의 설명이다."
        ],
        "revision_id": "sha256:9cf75535d07459d0cb339f947bcde03cd2f16266d39763d0f24b7603a6d3ec90",
        "text": "그렇다면 누가 아버지를 온전히 헤아려 이 말씀의 능력들도 찾아낼 수 있겠는가? 그분은 아버지의 말씀과 지혜이시며, 생성된 것들에게 낮추어 오셔서 자신을 낳으신 분을 알고 깨닫게 하신다. 거룩하게 함 자체와 생명 자체, 문과 목자와 길과 왕과 인도자가 되신다. 무엇보다 만물의 구주이며 생명을 주시는 분이며 빛이며 섭리가 되신다. 아버지는 자신에게서 나온 이처럼 선하고 창조하시는 아들을 생성된 것들에게 감추어 보이지 않게 하지 않으셨다. 오히려 그분을 통해 만물이 유지되고 살도록 하여, 날마다 그분을 모두에게 드러내신다. 또 그분 안에서 그분을 통해 자신도 드러내신다. 구주께서 말씀하신 것과 같다. “나는 아버지 안에 있고, 아버지는 내 안에 계시다.” 그러므로 말씀은 반드시 자신을 낳으신 분 안에 계시며, 태어나신 분은 아버지와 함께 영원히 계신다. 이 일이 그렇고 아무것도 그분 밖에 있지 않으며, 하늘과 땅과 그 안의 모든 것이 그분께 의존하는데도, 정신을 잃은 사람들은 그분을 아는 지식과 경건을 밀쳐 두었다. 존재하는 것들보다 존재하지 않는 것들을 높이고, 참으로 존재하시는 하나님 대신 존재하지 않는 것들을 신으로 만들었다. 창조자보다 피조물을 섬기며 무분별하고 불경한 일을 겪는다. 장인보다 작품에 감탄하고, 도시의 작품들을 보고 놀라면서 그것들을 만든 이를 짓밟는 사람과 같다. 혹은 악기는 칭찬하면서 그것을 만들고 조율한 이는 내쫓는 사람과 같다. 어리석고 눈이 크게 손상된 이들이다. 배를 만드는 이의 작업 없이, 건축가의 건축 없이, 음악가의 제작 없이 건물이나 배나 리라를 어떻게 알 수 있겠는가? 이런 생각을 하는 이는 정신을 잃어 모든 광기를 넘어선다. 이와 같이 하나님을 알아보지 못하고 그분의 말씀, 만물의 구주이며 우리 주 예수 그리스도를 숭배하지 않는 이들도 생각이 건전하지 않다고 나는 본다. 아버지는 그분을 통해 만물을 질서 있게 꾸미고 유지하며 전체를 돌보신다. 그리스도를 사랑하는 이여, 그대는 그분을 향한 믿음과 하나님 경외를 지니고 기뻐하며 희망을 가져라. 영혼이 그분의 법에 따라 질서 있게 꾸며진다면, 그분을 향한 믿음과 경건의 열매는 불멸과 하늘나라다. 그분을 따라 사는 이들에게 영원한 생명이 상인 것처럼, 덕의 길 대신 반대의 길을 걷는 이들에게는 심판의 날에 큰 수치와 용서받을 수 없는 위험이 있다. 진리의 길을 알고서도 자신이 안 것과 반대되는 일을 했기 때문이다."
      },
